{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is positive (≥0.33) and model shows over-optimism (e.g., overshoots recent highs).",
    "Reduce forecast volatility when sentiment is neutral or mildly positive (0.00–0.33) to avoid overreacting to short-term noise.",
    "Apply mean reversion bias: if model consistently overpredicts prices after a spike, reduce forecast by 5–10% of the spike magnitude.",
    "Increase forecast lag sensitivity when sentiment is negative (≤-0.25) — model should react more slowly to downward signals.",
    "Avoid forecasting sharp upward moves when sentiment is weak or neutral — price may not sustain momentum without strong signal confirmation."
  ]
}
